import { ComCodeParams, ComCodeResponse } from '~/entities/comcode/model/types';

export const getComBankInfo = (walletInsttCd: string | undefined | null, comCode: ComCodeResponse | undefined) => {
  if (!walletInsttCd || walletInsttCd === '' || walletInsttCd === 'null') return {};

  const bankInfo = comCode?.hash?.[walletInsttCd as keyof ComCodeParams];
  const bankName = bankInfo?.cdValueNm;
  const shortBankName = bankInfo?.atrb1;
  const bankCode = bankInfo?.cdValue;

  return { bankInfo, bankName, shortBankName, bankCode };
};
