import { useQueryClient } from '@tanstack/react-query';
import { useGetCodeManage } from '~/entities/comcode/api/use-comcode-api';
import { ComCodeType } from '~/entities/comcode/model/constants';
import { ComCodeResponse } from '~/entities/comcode/model/types';
import { queries } from '~/shared/api/query-keys';

export const useComCodeState = (id: ComCodeType) => {
  const queryClient = useQueryClient();
  const { data: comCode, isLoading } = useGetCodeManage(id);

  return {
    comCode,
    isLoading,
    setComCode: (update: ComCodeResponse) =>
      queryClient.setQueryData(queries.comCode.codeManage({ id }).queryKey, update),
    resetComCode: () =>
      queryClient.removeQueries({
        queryKey: queries.comCode.codeManage({ id }).queryKey,
      }),
  };
};
